#!/usr/bin/env bash
# Noethera Hermes theme (Claude style): warm Mono palette, chat bubbles, Open Sans, glass sidebar.
# One-file installer for a new device. Install Hermes first, then run:  bash noethera-theme-setup.sh
# Generated by noethera-agents/ui/build-portable.sh on 2026-10-21 10:08 from bea41c5+uncommitted. Do not edit by hand.
#
# What it does (safe to re-run; re-run after creating a new profile):
#   1. writes the skins (mono + default, with the Noethera CSS) into ~/.hermes and every profile
#      (existing files that differ are backed up to skins/.backup/)
#   2. activates the skin (display.skin = mono) in ~/.hermes and every profile
#   3. installs Open Sans if it is missing (Homebrew on macOS, else downloaded from Google Fonts)
#   4. sets the desktop sidebar translucency (glass) to the Noethera values
# Options:  --skin default   use the Nous palette instead of Mono (bubbles still apply)
#           --no-font        skip the font     --no-desktop   skip the translucency setting
set -euo pipefail

SKIN="mono"; DO_FONT=1; DO_DESKTOP=1
while [ $# -gt 0 ]; do
  case "$1" in
    --skin) SKIN="${2:?--skin needs a name}"; shift 2 ;;
    --no-font) DO_FONT=0; shift ;;
    --no-desktop) DO_DESKTOP=0; shift ;;
    -h|--help) sed -n '2,16p' "$0"; exit 0 ;;
    *) echo "Unknown option: $1" >&2; exit 2 ;;
  esac
done

# Root Hermes home. HERMES_HOME may point at a profile inside a Hermes session, so use our own variable.
ROOT="${NOETHERA_HERMES_ROOT:-$HOME/.hermes}"
command -v hermes >/dev/null 2>&1 || {
  echo "Hermes is not installed. Install it first:"
  echo "  curl -fsSL https://hermes-agent.nousresearch.com/install.sh | bash"
  exit 1
}
[ -f "$ROOT/config.yaml" ] || { echo "No $ROOT/config.yaml yet. Run 'hermes setup' once, then run this again."; exit 1; }

PAYLOAD="$(mktemp -d)"
trap 'rm -rf "$PAYLOAD"' EXIT
mkdir -p "$PAYLOAD/themes"

# ---------- payload: bubbles.css ----------
cat > "$PAYLOAD/bubbles.css" <<'__NOETHERA_THEME_EOF__'
/* Noethera chat style for the Hermes desktop app (installed into every theme in ui/themes/ by install-skin.sh).
   Modeled on Claude: Wira's messages are soft rounded cards on the right, agent replies are plain text, and the
   input is a roomy rounded card. Colors come from the active theme, so it works in Mono and Nous, light and dark.
   Selectors come from the Hermes desktop source (apps/desktop/src); adjust here if an update renames them. */

/* Fonts: Open Sans everywhere, JetBrains Mono for code (bundled with the app). Open Sans is installed on the Mac
   (`brew install --cask font-open-sans`) rather than loaded from Google Fonts, so startup needs no network and the
   text never swaps faces; without it the stack falls back to the system face. */
:root {
  --dt-font-sans: "Open Sans", -apple-system, BlinkMacSystemFont, "SF Pro Text", system-ui, sans-serif, "Apple Color Emoji" !important;
  --dt-font-mono: "JetBrains Mono", "SF Mono", ui-monospace, Menlo, monospace, "Apple Color Emoji" !important;
}

/* ---------- Warm Mono palette ---------- */
/* The desktop keeps its own Mono palette for a skin named `mono` (YAML colors don't reach it), so warm it up here:
   Claude's cream/ivory surfaces in light mode and warm charcoal in dark. applyTheme paints these vars inline on
   <html>, hence !important. Neutrals are set equal to the seeds so the desktop's seed/neutral mixes stay warm. */
:root[data-hermes-theme="mono"] {
  --theme-foreground: #141413 !important;
  --theme-background-seed: #faf9f5 !important;
  --theme-neutral-chrome: #faf9f5 !important;
  --theme-sidebar-seed: #f2f0e9 !important;
  --theme-neutral-sidebar: #f2f0e9 !important;
  --theme-card-seed: #faf9f5 !important;
  --theme-neutral-card: #faf9f5 !important;
  --theme-elevated-seed: #ffffff !important;
  --theme-bubble-seed: #f0eee6 !important;
  --dt-border: #e5e2d9 !important;
  --dt-input: #e5e2d9 !important;
  --dt-muted: #f0eee6 !important;
  --ui-bg-input: #ffffff !important;
  --noethera-user-bubble: #f0eee6;
  --noethera-composer-fill: #ffffff;
  /* Corners: Hermes scales every radius by 0.2 (rounded-md = 2px, nearly square). Claude rounds its rows, menus and
     buttons, so scale them up: rounded-md = 8px, rounded-lg ≈ 10px, rounded-xl ≈ 13px. */
  --radius-scalar: 0.8 !important;
  /* Hover/selected: a quiet warm tint of the text color, no accent hue (Claude's sidebar and menus). */
  --ui-row-hover-background: color-mix(in srgb, #1f1e1d 5%, transparent) !important;
  --ui-row-active-background: color-mix(in srgb, #1f1e1d 9%, transparent) !important;
  --ui-control-hover-background: color-mix(in srgb, #1f1e1d 6%, transparent) !important;
  --ui-control-active-background: color-mix(in srgb, #1f1e1d 10%, transparent) !important;
  /* Primary actions (Save, Confirm, toggles, links that use the brand color): Claude's clay orange. */
  --dt-primary: #c96442 !important;
  --dt-primary-foreground: #ffffff !important;
  /* Text selection: soft clay instead of the default yellow. */
  --ui-selection-background: color-mix(in srgb, #c96442 22%, transparent) !important;
}
:root[data-hermes-theme="mono"].dark {
  --theme-foreground: #faf9f5 !important;
  --theme-background-seed: #262624 !important;
  --theme-neutral-chrome: #262624 !important;
  --theme-sidebar-seed: #1f1e1d !important;
  --theme-neutral-sidebar: #1f1e1d !important;
  --theme-card-seed: #262624 !important;
  --theme-neutral-card: #262624 !important;
  --theme-elevated-seed: #30302e !important;
  --theme-bubble-seed: #141413 !important;
  --dt-border: #3e3e38 !important;
  --dt-input: #3e3e38 !important;
  --dt-muted: #30302e !important;
  --ui-bg-input: #30302e !important;
  --noethera-user-bubble: #141413;
  --noethera-composer-fill: #30302e;
  --ui-row-hover-background: color-mix(in srgb, #faf9f5 5%, transparent) !important;
  --ui-row-active-background: color-mix(in srgb, #faf9f5 9%, transparent) !important;
  --ui-control-hover-background: color-mix(in srgb, #faf9f5 6%, transparent) !important;
  --ui-control-active-background: color-mix(in srgb, #faf9f5 10%, transparent) !important;
  --ui-selection-background: color-mix(in srgb, #d97757 35%, transparent) !important;
}
/* Sidebar vs chat, like Claude: every pane zone (sessions, bots, files, terminal…) paints the editor surface, and
   only the chat transcript paints the chat surface. Give the zones the slightly darker sidebar tone and keep the
   transcript on the page cream. Skipped under window glass, which makes these surfaces translucent on purpose. */
:root[data-hermes-theme="mono"]:not([data-hermes-glass]) {
  --ui-editor-surface-background: var(--ui-bg-sidebar) !important;
  --ui-sidebar-surface-background: var(--ui-bg-sidebar) !important;
  --ui-chat-surface-background: var(--ui-bg-chrome) !important;
}
:root[data-hermes-theme="mono"] [data-slot="composer-root"] {
  --composer-fill: var(--noethera-composer-fill) !important;
}

/* ---------- 1:1 chats (Bot Chat, sessions) ---------- */
/* Wira's message: right-aligned card, not full width, scrolls with the conversation. */
[data-slot="aui_user-message-root"] {
  position: relative !important;
  top: auto !important;
  align-items: flex-end !important;
}
[data-slot="aui_user-message-root"] .composer-human-message {
  width: fit-content !important;
  max-width: min(75%, 680px) !important;
  margin-left: auto !important;
  border-radius: 14px !important;
  border-color: transparent !important;
  background: var(--noethera-user-bubble, color-mix(in srgb, currentColor 6%, transparent)) !important;
  -webkit-backdrop-filter: none !important;
  backdrop-filter: none !important;
  padding: 10px 16px !important;
}
/* Not sticky any more, so show long messages in full (the 2-line clamp was for the sticky header). */
[data-slot="aui_user-message-root"] .sticky-human-clamp {
  max-height: none !important;
  -webkit-mask-image: none !important;
  mask-image: none !important;
}
/* Side margins: the desktop insets the thread by 1.5rem but the input by 1rem, so their edges don't line up and both
   sit tight against the pane. Give both the same, roomier inset (grows with the pane, 1rem–2.5rem). The dock's
   extra 10px is the composer's 5px transparent grab margin on each side, so the visible card lands on the inset. */
:root {
  --noethera-chat-inset: clamp(1rem, 3.5%, 2.5rem);
}
[data-slot="aui_thread-content"] {
  padding-inline: var(--noethera-chat-inset) !important;
}
[data-slot="composer-dock"]:not([data-popped-out]) {
  width: calc(min(var(--composer-width), calc(100% - 2 * var(--noethera-chat-inset))) + 10px) !important;
}
/* Agent replies: plain text spanning the thread column (the desktop's own width: 100%), so their right edge lines
   up with the input card below. */
/* Replies get a little more leading for long reads. */
[data-slot="aui_assistant-message-root"] :is(p, li) {
  line-height: 1.65;
}

/* ---------- Group rooms ---------- */
/* Rooms are a plugin view with their own log and input (no data-slots beyond the message body), so these selectors
   lean on its Tailwind classes; recheck them against plugins/hermes-bots/group-chat-view.tsx after a desktop update. */
/* The log column: same side inset as 1:1 chats, a little more air between messages. */
div[class~="grid-cols-[minmax(0,1fr)]"][class~="gap-1.5"][class~="px-2.5"] {
  padding-inline: var(--noethera-chat-inset) !important;
  padding-top: 0.75rem;
  row-gap: 0.75rem !important;
}
/* Message text at the 1:1 chat size and color (the room defaults to 12px secondary text). */
[data-slot="group-chat-message-content"] {
  font-size: var(--conversation-text-font-size, 0.9375rem) !important;
  line-height: 1.65 !important;
  color: var(--ui-text-primary) !important;
}
/* Speaker name and time: readable, still quieter than the message. */
div.group:has(> div > [data-slot="group-chat-message-content"]) [class~="text-[0.7rem]"] {
  font-size: 0.8125rem !important;
}
div.group:has(> div > [data-slot="group-chat-message-content"]) [class~="text-[0.625rem]"] {
  font-size: 0.75rem !important;
}
/* Wira's row (the only row with the hover background): same card as in 1:1 chats. */
div.group[class~="rounded-md"][class~="bg-(--chrome-action-hover)"]:has(> div > [data-slot="group-chat-message-content"]) {
  width: fit-content;
  max-width: min(75%, 680px);
  margin-left: auto;
  border-radius: 14px;
  padding: 10px 16px;
  background: var(--noethera-user-bubble, color-mix(in srgb, currentColor 6%, transparent));
}
div.group[class~="rounded-md"][class~="bg-(--chrome-action-hover)"]:has(> div > [data-slot="group-chat-message-content"]) > div {
  text-align: left;
}
/* Agents' rows stay plain text across the full column; the speaker line already says who is talking. */

/* Room input: drop the bordered strip and use the same rounded card as the 1:1 input. */
div[class~="border-t"][class~="p-2"]:has(> form textarea.field-sizing-content[data-slot="textarea"]) {
  border-top: none !important;
  padding: 0.25rem var(--noethera-chat-inset) 0.75rem !important;
}
div[class~="border-t"][class~="p-2"] > form:has(textarea.field-sizing-content[data-slot="textarea"]) {
  padding: 0.625rem 0.625rem 0.625rem 0.875rem;
  border-radius: 20px;
  border: 1px solid color-mix(in srgb, currentColor 12%, transparent);
  background: var(--noethera-composer-fill, var(--composer-fill));
  box-shadow:
    0 1px 2px color-mix(in srgb, #000 4%, transparent),
    0 6px 24px color-mix(in srgb, #000 6%, transparent);
  transition: border-color 150ms ease, box-shadow 150ms ease;
}
div[class~="border-t"][class~="p-2"] > form:has(textarea.field-sizing-content[data-slot="textarea"]):focus-within {
  border-color: color-mix(in srgb, currentColor 22%, transparent);
  box-shadow:
    0 1px 2px color-mix(in srgb, #000 5%, transparent),
    0 8px 30px color-mix(in srgb, #000 9%, transparent);
}
/* The textarea sits flush inside the card: no own border, fill or focus ring. */
div[class~="border-t"][class~="p-2"] > form textarea.field-sizing-content[data-slot="textarea"] {
  border: none !important;
  background: transparent !important;
  box-shadow: none !important;
  outline: none !important;
  font-size: var(--conversation-text-font-size, 0.9375rem) !important;
  padding-inline: 0 !important;
}
/* Send ("New thread"): clay rounded button like the 1:1 send. */
div[class~="border-t"][class~="p-2"] > form button[type="submit"] {
  border-radius: 10px !important;
  background: #c96442 !important;
  color: #fff !important;
}
div[class~="border-t"][class~="p-2"] > form button[type="submit"]:hover:not(:disabled) {
  background: #b5573a !important;
}
div[class~="border-t"][class~="p-2"] > form button[type="submit"]:disabled {
  opacity: 0.4 !important;
}

/* ---------- Input ---------- */
/* A roomy rounded card with a hairline border and a soft shadow, like Claude's prompt box. Leave
   --composer-input-min-height alone: the desktop stacks the controls under the text once the editor is taller than
   one line (36px), so a taller minimum would push even a single word onto its own row. */
:root {
  --composer-surface-pad-x: 0.875rem !important;
  --composer-surface-pad-y: 0.75rem !important;
  --composer-row-gap: 0.5rem !important;
  --composer-input-max-height: 16rem !important;
}
[data-slot="composer-root"] {
  border-radius: 20px !important;
}
[data-slot="composer-surface"] {
  border: 1px solid color-mix(in srgb, currentColor 12%, transparent) !important;
  box-shadow:
    0 1px 2px color-mix(in srgb, #000 4%, transparent),
    0 6px 24px color-mix(in srgb, #000 6%, transparent) !important;
  transition: border-color 150ms ease, box-shadow 150ms ease;
}
[data-slot="composer-surface"]:focus-within {
  border-color: color-mix(in srgb, currentColor 22%, transparent) !important;
  box-shadow:
    0 1px 2px color-mix(in srgb, #000 5%, transparent),
    0 8px 30px color-mix(in srgb, #000 9%, transparent) !important;
}
/* Send / stop: Claude's clay-orange rounded square with a white arrow. */
[data-slot="composer-surface"] button[type="submit"] {
  width: 2rem !important;
  height: 2rem !important;
  border-radius: 10px !important;
  background: #c96442 !important;
  color: #fff !important;
  border: none !important;
}
[data-slot="composer-surface"] button[type="submit"]:hover:not(:disabled) {
  background: #b5573a !important;
}
[data-slot="composer-surface"] button[type="submit"]:disabled {
  opacity: 0.4 !important;
}

/* ---------- Tabs ---------- */
/* Pane tabs (chat tabs on top, Sessions/Bots/Files/Terminal in the sidebar) default to 11px uppercase labels with
   divider lines and an underline on the active tab. Chrome-style instead: sentence-case 13px labels; inactive tabs
   sit flat on the strip with a short divider between them; the active tab rises out of the strip in the chat
   surface color, rounded on top and flaring into the content below, so it reads as part of the page it opens.
   Strips keep their place and their titlebar height; a strip below the titlebar grows from 28px to 34px. Vertical
   rails (collapsed zones) are left alone. Tabs are matched by data-tree-tab too: a session tab is wrapped in a
   context-menu trigger whose asChild merge replaces data-slot="pane-tab". */
[data-zone-tabstrip][class~="h-7"]:not([class~="absolute"]) {
  height: 2.125rem !important;
}
/* The strip (and the header row it sits in, beside the traffic lights) takes the solid sidebar tone, a step darker
   than the chat surface, so the active tab can rise out of it. Solid tokens, not the *-surface-background ones:
   those can match each other or go transparent under window glass. */
[data-panel-header],
[data-zone-tabstrip] {
  background-color: var(--ui-bg-sidebar) !important;
}
[data-zone-tabstrip] > [role="tablist"] {
  align-items: stretch;
  padding-inline: 10px;
}
:is([data-slot="pane-tab"], [data-tree-tab]):not([data-vertical]) {
  --noethera-tab-active: var(--ui-bg-chrome);
  height: auto !important;
  margin-top: 5px;
  border-left: none !important;
  border-radius: 10px 10px 0 0;
  font-size: 0.8125rem !important;
  background-color: transparent !important;
  /* Divider on the right edge of each inactive tab. */
  background-image: linear-gradient(var(--dt-border), var(--dt-border));
  background-size: 1px 45%;
  background-position: right center;
  background-repeat: no-repeat;
  box-shadow: none !important;
  transition: background-color 120ms ease, color 120ms ease;
}
/* No divider next to the active tab, on either side, nor on a hovered tab. */
:is([data-slot="pane-tab"], [data-tree-tab]):not([data-vertical]):is([data-active="true"], :hover, :has(+ [data-active="true"]), :has(+ * > [data-active="true"])) {
  background-image: none;
}
:is([data-slot="pane-tab"], [data-tree-tab]):not([data-vertical]):not([data-active="true"]):hover {
  background-color: var(--ui-control-hover-background) !important;
}
:is([data-slot="pane-tab"], [data-tree-tab])[data-active="true"]:not([data-vertical]) {
  z-index: 1;
  color: var(--ui-text-primary);
  background-color: var(--noethera-tab-active) !important;
}
/* The flare: two 10px quarter-circles cut out of the active color at the tab's bottom corners. */
:is([data-slot="pane-tab"], [data-tree-tab])[data-active="true"]:not([data-vertical])::before,
:is([data-slot="pane-tab"], [data-tree-tab])[data-active="true"]:not([data-vertical])::after {
  content: "";
  position: absolute;
  bottom: 0;
  width: 10px;
  height: 10px;
  pointer-events: none;
}
:is([data-slot="pane-tab"], [data-tree-tab])[data-active="true"]:not([data-vertical])::before {
  left: -10px;
  background: radial-gradient(circle at 0 0, transparent 9.5px, var(--noethera-tab-active) 10px);
}
:is([data-slot="pane-tab"], [data-tree-tab])[data-active="true"]:not([data-vertical])::after {
  right: -10px;
  background: radial-gradient(circle at 100% 0, transparent 9.5px, var(--noethera-tab-active) 10px);
}
:is([data-slot="pane-tab"], [data-tree-tab]):not([data-vertical]) [class~="uppercase"] {
  text-transform: none !important;
  letter-spacing: normal !important;
}
/* Breathing room inside the tab (the label keeps its own px-2; the status dot sits tight beside it). */
:is([data-slot="pane-tab"], [data-tree-tab]):not([data-vertical]) {
  padding-inline: 0.375rem;
}
/* Close ✕, Chrome-style: always shown on the active tab, and on any other tab while hovered, so a tab can be closed
   without opening it first. Every closeable tab reserves the slot at its right end, so the ✕ never sits on the
   label and tabs don't change width on hover. The desktop's hover fade-mask on the label is dropped (it assumed the
   ✕ overlapped the text). */
:is([data-slot="pane-tab"], [data-tree-tab])[data-closeable]:not([data-vertical]) {
  --pane-tab-close-width: 1.25rem;
  padding-right: 1.375rem;
}
:is([data-slot="pane-tab"], [data-tree-tab])[data-closeable]:not([data-vertical]):is([data-active="true"], :hover) > span[class~="absolute"][class~="right-0"] {
  opacity: 1 !important;
  pointer-events: auto !important;
}
:is([data-slot="pane-tab"], [data-tree-tab])[data-closeable]:not([data-vertical]):hover > .pane-tab-content {
  -webkit-mask-image: none !important;
  mask-image: none !important;
}
:is([data-slot="pane-tab"], [data-tree-tab])[data-closeable]:not([data-vertical]) > span[class~="absolute"][class~="right-0"] {
  right: 0.25rem !important;
  align-items: center !important;
}
:is([data-slot="pane-tab"], [data-tree-tab])[data-closeable]:not([data-vertical]) > span[class~="absolute"][class~="right-0"] > * {
  width: 1.25rem !important;
  height: 1.25rem !important;
  border-radius: 6px;
}
:is([data-slot="pane-tab"], [data-tree-tab])[data-closeable]:not([data-vertical]) > span[class~="absolute"][class~="right-0"] > *:hover {
  background-color: var(--ui-control-hover-background) !important;
}

/* ---------- Pane seams ---------- */
/* Panes (sidebar, chat, tools) are split by a sash whose hairline sits at opacity 0.1 until hovered, so the
   sidebar/chat boundary is invisible on a white theme. Show the hairline at full strength all the time. */
[role="separator"][data-sash-overlap="trailing"] > span:first-child {
  opacity: 1 !important;
}
__NOETHERA_THEME_EOF__

# ---------- payload: themes/default.yaml ----------
cat > "$PAYLOAD/themes/default.yaml" <<'__NOETHERA_THEME_EOF__'
# Bubble layer for the desktop "Nous" theme (display.skin: default). Only adds customCSS; the desktop keeps its
# own Nous palette for a user skin with a built-in name.
name: default
__NOETHERA_THEME_EOF__

# ---------- payload: themes/mono.yaml ----------
cat > "$PAYLOAD/themes/mono.yaml" <<'__NOETHERA_THEME_EOF__'
# Bubble layer for the desktop "Mono" theme. The desktop keeps its own Mono palette; the colors below copy the
# built-in CLI mono skin so the terminal UI stays grayscale (user skins otherwise inherit the gold default).
name: mono
description: Monochrome — clean grayscale (with Noethera chat bubbles)
colors:
  banner_border: "#5E5E5E"
  banner_title: "#e6edf3"
  banner_accent: "#aaaaaa"
  banner_dim: "#606060"
  banner_text: "#c9d1d9"
  ui_accent: "#aaaaaa"
  ui_label: "#888888"
  ui_ok: "#888888"
  ui_error: "#cccccc"
  ui_warn: "#999999"
  prompt: "#c9d1d9"
  input_rule: "#606060"
  response_border: "#aaaaaa"
  status_bar_bg: "#1F1F1F"
  status_bar_text: "#C9D1D9"
  status_bar_strong: "#E6EDF3"
  status_bar_dim: "#777777"
  status_bar_good: "#B5B5B5"
  status_bar_warn: "#AAAAAA"
  status_bar_bad: "#D0D0D0"
  status_bar_critical: "#F0F0F0"
  session_label: "#888888"
  session_border: "#5E5E5E"
  completion_menu_bg: "#1F1F1F"
  completion_menu_current_bg: "#464646"
  selection_bg: "#505050"
  shell_dollar: "#aaaaaa"
  voice_status_bg: "#1F1F1F"
branding:
  help_header: "[?] Available Commands"
tool_prefix: "┊"
__NOETHERA_THEME_EOF__

[ -f "$PAYLOAD/themes/$SKIN.yaml" ] || { echo "Unknown skin '$SKIN' (available: $(ls "$PAYLOAD/themes" | sed 's/\.yaml$//' | tr '\n' ' '))" >&2; exit 2; }

# 1. Skins into the root and every profile (the desktop reads the active profile's home).
build() { cat "$1"; printf '\ncustomCSS: |\n'; sed 's/^/  /' "$PAYLOAD/bubbles.css"; }
stamp="$(date +%Y%m%d-%H%M%S)"
homes=("$ROOT")
for p in "$ROOT"/profiles/*/; do [ -d "$p" ] && homes+=("${p%/}"); done
for home in "${homes[@]}"; do
  mkdir -p "$home/skins"
  for theme in "$PAYLOAD"/themes/*.yaml; do
    name="$(basename "$theme")"; target="$home/skins/$name"
    build "$theme" > "$PAYLOAD/built.yaml"
    if [ -f "$target" ] && ! cmp -s "$PAYLOAD/built.yaml" "$target"; then
      mkdir -p "$home/skins/.backup"; cp "$target" "$home/skins/.backup/$name.$stamp"
    fi
    cp "$PAYLOAD/built.yaml" "$target"; chmod 644 "$target"
  done
  rm -f "$home/skins/noethera.yaml"
done
echo "Skins installed in ${#homes[@]} Hermes home(s): $ROOT and $(( ${#homes[@]} - 1 )) profile(s)"

# 2. Activate the skin everywhere (hermes config set writes valid YAML; never hand-edit config.yaml).
for home in "${homes[@]}"; do
  [ -f "$home/config.yaml" ] || continue
  HERMES_HOME="$home" hermes config set display.skin "$SKIN" >/dev/null 2>&1 \
    && echo "  display.skin = $SKIN  ($home)" || echo "  Could not set the skin in $home; run: HERMES_HOME=$home hermes config set display.skin $SKIN"
done

# 3. Open Sans (bubbles.css uses the installed font, not the network).
if [ "$DO_FONT" = 1 ]; then
  case "$(uname -s)" in
    Darwin) fontdir="$HOME/Library/Fonts"; have() { compgen -G "$HOME/Library/Fonts/OpenSans*" >/dev/null || compgen -G "/Library/Fonts/OpenSans*" >/dev/null; } ;;
    *)      fontdir="$HOME/.local/share/fonts"; have() { fc-list 2>/dev/null | grep -qi "Open Sans"; } ;;
  esac
  if have; then
    echo "Open Sans already installed"
  elif [ "$(uname -s)" = Darwin ] && command -v brew >/dev/null 2>&1 && brew install --cask font-open-sans >/dev/null 2>&1; then
    echo "Open Sans installed (Homebrew)"
  else
    mkdir -p "$fontdir"
    base="https://github.com/google/fonts/raw/main/ofl/opensans"
    if curl -fsSL "$base/OpenSans%5Bwdth,wght%5D.ttf" -o "$fontdir/OpenSans[wdth,wght].ttf" \
       && curl -fsSL "$base/OpenSans-Italic%5Bwdth,wght%5D.ttf" -o "$fontdir/OpenSans-Italic[wdth,wght].ttf"; then
      command -v fc-cache >/dev/null 2>&1 && fc-cache -f "$fontdir" >/dev/null 2>&1 || true
      echo "Open Sans installed (Google Fonts) in $fontdir"
    else
      echo "Note: could not install Open Sans; the app falls back to the system font. Install it manually later."
    fi
  fi
fi

# 4. Desktop glass sidebar (stored by the app, not in the skin).
if [ "$DO_DESKTOP" = 1 ]; then
  case "$(uname -s)" in
    Darwin) appdir="${NOETHERA_APP_DIR:-$HOME/Library/Application Support/Hermes}" ;;
    *)      appdir="${NOETHERA_APP_DIR:-${XDG_CONFIG_HOME:-$HOME/.config}/Hermes}" ;;
  esac
  mkdir -p "$appdir"
  cat > "$appdir/translucency.json" <<'JSON'
{
  "intensity": 29,
  "fade": 0,
  "mode": "glass",
  "material": "header",
  "scope": "sidebar"
}
JSON
  echo "Desktop translucency set (glass sidebar)"
fi

echo
echo "Done. Quit and reopen the Hermes desktop app (Cmd+Q) to load the fonts and sidebar; the CLI/TUI repaint live."
echo "New profile later? Run this script again. Revert: hermes config set display.skin default"
